sys_script_fix.script:
function defaultSubscriptionPeriod() {
	var grEnt = new GlideRecord('alm_license');
	grEnt.addQuery('product_type', 'subscription');
	grEnt.addQuery('subscription_period', '');
	grEnt.setValue('subscription_period', 'entire_subscription_period');
	grEnt.updateMultiple();
}
defaultSubscriptionPeriod();
